import random, time
customers = [{"id": i, "name": f"C{i}"} for i in range(50_000)]
orders = [{"order_id": j, "customer_id": random.randrange(50_000)}
          for j in range(50_000)]

# O(n * m): for every order, scan the customer list
def join_slow(orders, customers):
    out = []
    for o in orders:
        for c in customers:
            if c["id"] == o["customer_id"]:
                out.append((o["order_id"], c["name"]))
                break
    return out

# O(n + m): build a dict once, then each lookup is O(1) on average
def join_fast(orders, customers):
    by_id = {c["id"]: c for c in customers}
    return [(o["order_id"], by_id[o["customer_id"]]["name"])
            for o in orders if o["customer_id"] in by_id]

t = time.perf_counter()
join_fast(orders, customers)
print("fast:", round(time.perf_counter() - t, 3), "seconds")
# join_slow on this data does about a billion comparisons.
